def solve():
    T = int(input())
    results = []

    # Let's compute f(N) for all N from 1 to 10^5 manually for small values
    # and look for a pattern

    # f(0) = 0
    f = [0] * (1000)

    for N in range(1, 1000):
        if N % 2 == 1:
            f[N] = N - f[N - 1]
        else:
            f[N] = max(N - f[N - 1], N - f[N // 2])

    # Print values to find a pattern
    for N in range(1, 1000):
        print(f"N={N}: f(N)={f[N]}")

solve()
"}

