def solve():
    T = int(input())
    results = []

    # Use memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def f(N):
        if N == 0:
            return 0

        if N % 2 == 1:
            return N - f(N - 1)
        else:
            return max(N - f(N - 1), N - f(N // 2))

    for _ in range(T):
        N = int(input())
        results.append(str(f(N)))

    print("\n".join(results))

solve()
"}

