import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""

    dx_map = {'R': 1, 'L': -1, 'U': 0, 'D': 0}
    dy_map = {'U': 1, 'D': -1, 'R': 0, 'L': 0}

    result = 0
    for i in range(n):
        dx = 0
        dy = 0
        for j in range(i, n):
            move = s[j]
            dx += dx_map[move]
            dy += dy_map[move]
            if dx == 0 and dy == 0:
                result += 1

    print(result)

if __name__ == "__main__":
    solve()
"}

