import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse inputs as integers
    nums = []
    for item in data:
        if item.isdigit():
            nums.append(int(item))
        elif item == "0":
            nums.append(0)

    if not nums:
        return

    TUX = nums[0]
    FOO = 0
    BAR = 0
    BAZ = 0
    QUZ = 1

    for i in range(1, len(nums)):
        PUR = nums[i]
        FOO += PUR
        BAR += 1

        if FOO * QUZ > BAR * BAZ:
            BAZ = FOO
            QUZ = BAR

    # Print with 6 decimal places
    print(f"{BAZ / QUZ:.6f}")

if __name__ == "__main__":
    solve()
"}

