import sys

def is_lonely(n):
    """Check if a number n is lonely in the group 1..n"""
    if n == 1:
        return True

    # A number is lonely if it has no friends
    # Two numbers a and b are friends if their GCD, a/GCD, b/GCD can form a triangle
    # For a to have a friend b, there must be some b such that:
    # gcd(a,b) + a/gcd(a,b) > b/gcd(a,b)
    # gcd(a,b) + b/gcd(a,b) > a/gcd(a,b)
    # a/gcd(a,b) + b/gcd(a,b) > gcd(a,b)

    # We'll iterate through all potential friends
    for b in range(1, n + 1):
        if b == n:
            continue  # a and b must be different

        # Find GCD
        g = gcd(a=n, b=b)

        # Check if we can form a triangle
        if g + a // g > b // g and g + b // g > a // g and a // g + b // g > g:
            return False

    return True

def solve():
    # Read input
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    cases = list(map(int, data[1:1 + t]))

    # Precompute answers
    max_n = max(cases) if cases else 0
    answers = {}
    for n in range(1, max_n + 1):
        if is_lonely(n):
            answers[n] = 1
        else:
            answers[n] = 0

    # Output answers
    for n in cases:
        print(answers[n])

def gcd(a, b):
    """Compute GCD using Euclidean algorithm"""
    while b:
        a, b = b, a % b
    return a

if __name__ == "__main__":
    solve()
"}

