def main():
    n, q = map(int, input().split())
    painters = []
    all_sections = set(range(1, n + 1))

    for _ in range(q):
        l, r = map(int, input().split())
        painter = set(range(l, r + 1))
        painters.append(painter)

    # Calculate sections only covered by each painter
    only_by = []
    for i in range(q):
        # Section covered by painter i but no other painter
        only = painters[i].copy()
        for j in range(q):
            if i != j:
                only -= painters[j]
        only_by.append(only)

    # We need to skip 2 painters
    max_painted = 0

    # Try all pairs of skipped painters
    for skip1 in range(q):
        for skip2 in range(q):
            if skip1 == skip2:
                continue

            # Sections not painted if we skip skip1 and skip2
            not_painted = only_by[skip1].union(only_by[skip2])
            painted = all_sections - not_painted

            if len(painted) > max_painted:
                max_painted = len(painted)

    print(max_painted)

if __name__ == "__main__":
