import sys

def solve():
    data = sys.stdin.read().strip().split()
    T = int(data[0])
    results = []

    for i in range(1, T + 1):
        N = int(data[i])
        ans = 0
        turn = True

        while N > 0:
            if turn:
                # Mr. Chanek's turn - he wants to maximize his coins
                # If N is odd, only option is to take 1
                if N % 2 == 1:
                    ans += 1
                    N -= 1
                else:
                    # Even N, Mr. Chanek can choose between taking 1 or taking half
                    # We need to simulate both options to find which gives more coins
                    option1 = 1 + solve_game(N-1)
                    option2 = N//2 + solve_game(N//2)

                    if option1 >= option2:
                        ans += 1
                        N -= 1
                    else:
                        ans += N//2
                        N -= N//2
            else:
                # Opponent's turn - they play optimally too
                if N % 2 == 1:
                    N -= 1
                else:
                    N -= N//2
            turn = not turn

        results.append(str(ans))

    sys.stdout.write("\n".join(results))

# Helper function to solve a subgame
def solve_game(n):
    if n == 0:
        return 0
    ans = 0
    turn = True

    while n > 0:
        if turn:
            if n % 2 == 1:
                ans += 1
                n -= 1
            else:
                # This is tricky, we need to simulate both options again
                option1 = 1 + solve_game(n-1)
                option2 = n//2 + solve_game(n//2)

                if option1 >= option2:
                    ans += 1
                    n -= 1
                else:
                    ans += n//2
                    n -= n//2
        else:
            if n % 2 == 1:
                n -= 1
            else:
                n -= n//2
        turn = not turn

    return ans

