def derangement(n, MOD):

    # Recursive formula: D(n) = (n - 1) * (D(n - 1) + D(n - 2))

    # Precompute D for small n
    D = [0, 1]
    for i in range(2, n + 1):
        D.append((i - 1) * (D[i - 1] + D[i - 2]) % MOD)

    return D[n]

