    if num not in used:
        available.append(num)

from collections import defaultdict

# dp[mask] = number of ways to fill positions indicated by mask
# mask is a bitmask of positions

def bit_count(mask):
    """Count the number of set bits in mask"""
    count = 0
    while mask > 0:
        count += mask & 1
        mask >>= 1
    return count

dp = defaultdict(int)
dp[0] = 1

for i in range(len(available)):
    num = available[i]
    # Try placing this number in each -1 position
    for mask, ways in dp.items():
        # Find all -1 positions
        for pos in range(n):
            if perm[pos] == -1 and not (mask & (1 << pos)):
                new_mask = mask | (1 << pos)
                # Check if placing num at pos creates a fixed point
                if num == (pos + 1):  # num is at position pos (1-indexed)
                    continue
                dp[new_mask] = (dp[new_mask] + ways) % 1000000007

# The answer is the number of ways to fill all -1 positions
print(dp[(1 << n) - 1])
