def solve():
    n, k, M = map(int, input().split())
    t = list(map(int, input().split()))
    t.sort()

    # Prefix sums of sorted t
    prefix = [0] * (k + 1)
    for i in range(1, k + 1):
        prefix[i] = prefix[i - 1] + t[i - 1]

    # dp[i][j] = max points with first i tasks and time j
    dp = [0] * (M + 1)

    for i in range(n):
        # Current task
        new_dp = dp[:]

        # Try solving 0 to k subtasks
        for m in range(k + 1):
            time_cost = prefix[m]
            if time_cost > M:
                break

            for j in range(M - time_cost + 1):
                if dp[j] > 0:
                    new_dp[j + time_cost] = max(new_dp[j + time_cost], dp[j] + m + (1 if m == k else 0))

        dp = new_dp

    print(max(dp))

solve()
"}

