n, m = map(int, input().split())
grid = []
for _ in range(n):
    grid.append(list(map(int, input().split())))

# Iahub: (0,0) -> (i,j) and (i,j) -> (n-1,m-1)
# Iahubina: (n-1,0) -> (i,j) and (i,j) -> (0,m-1)

# Precompute DP tables
# dp1[i][j] = max calories Iahub can get from (0,0) to (i,j)
dp1 = [[0] * m for _ in range(n)]
dp1[0][0] = grid[0][0]
for i in range(n):
    for j in range(m):
        if i > 0:
            dp1[i][j] = max(dp1[i][j], dp1[i-1][j])
        if j > 0:
            dp1[i][j] = max(dp1[i][j], dp1[i][j-1])
        dp1[i][j] += grid[i][j]

# dp2[i][j] = max calories Iahub can get from (i,j) to (n-1,m-1)
dp2 = [[0] * m for _ in range(n)]
dp2[n-1][m-1] = grid[n-1][m-1]
for i in range(n-1, -1, -1):
    for j in range(m-1, -1, -1):
        if i < n-1:
            dp2[i][j] = max(dp2[i][j], dp2[i+1][j])
        if j < m-1:
            dp2[i][j] = max(dp2[i][j], dp2[i][j+1])
        dp2[i][j] += grid[i][j]

# dp3[i][j] = max calories Iahubina can get from (n-1,0) to (i,j)
dp3 = [[0] * m for _ in range(n)]
dp3[n-1][0] = grid[n-1][0]
for i in range(n-1, -1, -1):
    for j in range(m):
        if i > 0:
            dp3[i][j] = max(dp3[i][j], dp3[i-1][j])
        if j < m-1:
            dp3[i][j] = max(dp3[i][j], dp3[i][j+1])
        dp3[i][j] += grid[i][j]

# dp4[i][j] = max calories Iahubina can get from (i,j) to (0,m-1)
dp4 = [[0] * m for _ in range(n)]
dp4[0][m-1] = grid[0][m-1]
for i in range(0, n):
    for j in range(m-1, -1, -1):
        if i < n-1:
            dp4[i][j] = max(dp4[i][j], dp4[i+1][j])
        if j > 0:
            dp4[i][j] = max(dp4[i][j], dp4[i][j-1])
        dp4[i][j] += grid[i][j]

# Find maximum total gain
max_gain = 0
for i in range(n):
    for j in range(m):
        total = dp1[i][j] + dp2[i][j] + dp3[i][j] + dp4[i][j]
        total -= grid[i][j]  # Subtract the meeting cell twice
        max_gain = max(max_gain, total)

print(max_gain)
