def solve():
    t = int(input())
    for _ in range(t):
        n, m, k = map(int, input().split())
        a = list(map(int, input().split()))

        # dp[l][r][c]: max guaranteed value from subarray a[l..r] with c controls left
        dp = [[[0] * (n + 1) for _ in range(n + 1)] for __ in range(n + 1)]

        # Base case: it's our turn (c == 0)
        for l in range(n):
            for r in range(n):
                dp[l][r][0] = max(a[l], a[r])

        # For c > 0, it's not our turn - we have c controls left
        # We can either control the current person or not
        for c in range(1, n + 1):
            for l in range(n):
                for r in range(n):
                    # Option 1: we control the current person
                    # We choose first or last to maximize our guaranteed value
                    option1 = max( min(dp[l+1][r][c-1], a[l]),  # control and take first
                                 min(dp[l][r-1][c-1], a[r])   # control and take last
                               )
                    # Option 2: the current person is uncontrolled
                    # They choose the option that minimizes our guaranteed value
                    if l < r:
                        option2 = min( dp[l+1][r][c],  # uncontrolled takes first
                                      dp[l][r-1][c]    # uncontrolled takes last
                                    )
                    else:
                        # if only one element left, it's our turn, so guaranteed value is that element
                        option2 = a[l]  # or a[r]

                    dp[l][r][c] = option1  # Actually, should we take max(option1, option2)?

        # You're in position m, so there are m-1 people before you
        # We can control up to k people
        result = dp[0][n-1][k]
        print(result)

solve()

