def solve():
    t = int(input())
    for _ in range(t):
        n, x, y = map(int, input().split())
        b = list(map(int, input().split()))

        # Count frequencies in Bob's guess
        from collections import defaultdict
        freq_b = defaultdict(int)
        for color in b:
            freq_b[color] += 1

        # Count of each color we need in Alice's code
        needed = defaultdict(int)

        # We need y total matching colors
        # At exact positions, we get x matches
        # So we need y-x matches from different positions

        # Try to match colors that appear at least twice first for exact matches
        matches = []
        for i in range(n):
            if len(matches) < x:
                if freq_b[b[i]] >= 2:
                    matches.append(i)
                    freq_b[b[i]] -= 1

        # Fill in the exact matches
        a = [0] * n
        for i in matches:
            a[i] = b[i]

        # For the remaining positions, we need y-x matches from different positions
        # We can use either the remaining colors from Bob's guess
        # or new colors

        remaining = []
        for color in freq_b:
            if freq_b[color] > 0:
                remaining.append(color)

        for i in range(n):
            if a[i] == 0:
                # Try to match a different color
                if remaining:
                    a[i] = remaining[0]
                    remaining.pop(0)
                else:
                    # Use a new color (n+1)
                    a[i] = n + 1

        # Check if we satisfied the constraints
        x_actual = sum(1 for i in range(n) if a[i] == b[i])
        freq_a = defaultdict(int)
        for color in a:
            freq_a[color] += 1
        y_actual = 0
        for color in freq_b:
            y_actual += min(freq_b[color], freq_a.get(color, 0))

        if x_actual == x and y_actual == y:
            print("YES")
            print(" ".join(map(str, a)))
        else:
            print("NO")

