import sys

def grundy(v, memo):
    """Compute the Grundy number for a single cycle of size v"""
    if v not in memo:
        reachable = set()
        for p in range(1, v):
            reachable.add(grundy(p, memo) ^ grundy(v - p, memo))
        memo[v] = len(reachable)
    return memo[v]

# Dictionary to store computed Grundy numbers
d = {}

# Read input
n = int(sys.stdin.readline())
nums = list(map(int, sys.stdin.readline().split()))

# Add cycles and compute Grundy for each
output = []
for v in nums:
    # Ignore cycles of size 1 (Grundy 0)
    if v == 1:
        output.append(2)
    else:
        # Compute Grundy number for this cycle
        g = grundy(v, d)
        # XOR with all previously added cycles
        total = 0
        for num in nums:
            if num == 1:
                continue
            total ^= grundy(num, d)
        output.append(1 if total != 0 else 2)

print(' '.join(map(str, output)))
