import sys

def solve() -> None:
    input = sys.stdin.read().split()
    if not input:
        return
    data = iter(input)
    n = int(next(data))
    m = int(next(data))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(data))
        v = int(next(data))
        adj[u].append(v)
        adj[v].append(u)

    # Compute degrees
    degree = [0] * (n + 1)
    for i in range(1, n + 1):
        degree[i] = len(adj[i])

    # Longest increasing path ending at each point
    path_length = [1] * (n + 1)  # Minimum path length is 1 (the point itself)

    # Topological sort by point number
    for i in range(1, n + 1):
        # Look at neighbors with smaller numbers
        for neighbor in adj[i]:
            if neighbor < i:
                if path_length[neighbor] < path_length[i] + 1:
                    path_length[neighbor] = path_length[i] + 1

    # Calculate beauty
    max_beauty = 0
    for i in range(1, n + 1):
        beauty = path_length[i] * degree[i]
        if beauty > max_beauty:
            max_beauty = beauty

    print(max_beauty)

if __name__ == "__main__":
    solve()
