import sys

def solve():
    n = int(sys.stdin.readline())

    # For each set of vitamins, track the minimum cost
    min_cost = {}

    for i in range(n):
        line = sys.stdin.readline().strip()
        parts = line.split()
        c = int(parts[0])
        s = parts[1]

        # Parse vitamins
        vitamins = set()
        for ch in s:
            vitamins.add(ch)

        # Update minimum cost for each subset of vitamins that includes all vitamins in this juice
        # To be more specific, we need to track the minimum cost for each exact set of vitamins

        # We can use bit manipulation for efficiency
        # A, B, C correspond to 1, 2, 4
        mask = 0
        for ch in s:
            if ch == 'A':
                mask |= 1
            elif ch == 'B':
                mask |= 2
            elif ch == 'C':
                mask |= 4

        # Update minimum cost for all supersets of this mask
        # A superset includes all vitamins in this juice and possibly more

        # We need to consider all supersets of this mask
        # For a mask with k bits set, there are 2^(3-k) supersets

        # Start with the given mask
        current_mask = mask

        # Find all supersets
        supersets = [current_mask]

        # Generate all supersets of the given mask
        while True:
            found = False
            for i in range(7):
                if (current_mask & (1 << i)) != 0:
                    continue

                # Try adding each missing vitamin
                new_mask = current_mask | (1 << i)
                supersets.append(new_mask)
                current_mask = new_mask
                found = True

            if not found:
                break

        # Update the minimum cost for each superset
        for superset in supersets:
            if superset not in min_cost:
                min_cost[superset] = float('inf')
            if min_cost[superset] > c:
                min_cost[superset] = c

    # Try to get all three vitamins
    # We need to combine sets such that their union is all three vitamins

    ans = float('inf')

    # Try all combinations of 1, 2, or 3 sets
    # 1 set: full mask
    if 0b111 in min_cost:
        ans = min(ans, min_cost[0b111])

    # 2 sets:
    for mask1 in min_cost:
        for mask2 in min_cost:
            union_mask = mask1 | mask2
            if union_mask == 0b111:
                ans = min(ans, min_cost[mask1] + min_cost[mask2])

    # 3 sets:
    for mask1 in min_cost:
        for mask2 in min_cost:
            for mask3 in min_cost:
                union_mask = mask1 | mask2 | mask3
                if union_mask == 0b111:
                    ans = min(ans, min_cost[mask1] + min_cost[mask2] + min_cost[mask3])

    if ans == float('inf'):
        print(-1)
    else:
        print(ans)

if __name__ == '__main__':
    solve()
