from functools import lru_cache

def solve():
    r, s, p = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dp(r, s, p):
        # Return (prob_rock, prob_scissors, prob_paper)
        if r == 0:
            return (0.0, 1.0, 0.0)
        if s == 0:
            return (1.0, 0.0, 0.0)
        if p == 0:
            return (1.0, 0.0, 0.0)

        # Total number of pairs meeting
        total_pairs = r * s + s * p + p * r

        # Probability of rock killing scissors
        prob_rk = (s * r) / total_pairs
        # Probability of scissors killing paper
        prob_sk = (s * p) / total_pairs
        # Probability of paper killing rock
        prob_pk = (p * r) / total_pairs

        # After rock kills scissors, we have (r-1, s-1, p)
        # After scissors kill paper, we have (r, s-1, p-1)
        # After paper kills rock, we have (r-1, s, p-1)

        pr, ps, pp = dp(r-1, s-1, p)
        pr2, ps2, pp2 = dp(r, s-1, p-1)
        pr3, ps3, pp3 = dp(r-1, s, p-1)

        # Weighted average of the resulting probabilities
        final_r = prob_rk * pr + prob_sk * pr2 + prob_pk * pr3
        final_s = prob_rk * ps + prob_sk * ps2 + prob_pk * ps3
        final_p = prob_rk * pp + prob_sk * pp2 + prob_pk * pp3

        return (final_r, final_s, final_p)

    prob_rock, prob_scissors, prob_paper = dp(r, s, p)
    print(f"{prob_rock:.15f} {prob_scissors:.15f} {prob_paper:.15f}")

if __name__ == "__main__":
    solve()
"}

