    for b in B:
        if b % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    if even_count > 0 and odd_count > 0:
        # Need to remove all of one parity
        removed = min(even_count, odd_count)

        # Remove the smaller count of elements
        if even_count < odd_count:
            # Remove all even elements
