import math

def solve():
    n, k = map(int, input().split())
    if k == 1:
        print("Yes")
        return
    if k > 32:
        print("No")
        return
    # compute lcm(2, 3, ..., k)
    lcm_val = 1
    for i in range(2, k + 1):
        lcm_val = lcm_val * i // math.gcd(lcm_val, i)
    if (n + 1) % lcm_val == 0:
        print("Yes")
    else:
        print("No")

