def find_min_layers(N):

    # Create a list of intervals
    intervals = []
    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            intervals.append((i, j))

    # For each interval, track which layers it can go into
    # Layer assignment: greedily assign to lowest layer
    layers = []

    for (l, r) in intervals:
        # Find all layers where there's no overlap
        valid_layers = []
        for layer_idx in range(len(layers)):
            # Check if this interval overlaps with any interval in this layer
            overlaps = False
            for (layer_l, layer_r) in layers[layer_idx]:
                # Overlap if the intervals have common interior points
                if not (layer_r <= l or layer_l >= r):
                    overlaps = True
                    break
            if not overlaps:
                valid_layers.append(layer_idx)

        # If no valid layers, create a new one
        if valid_layers:
            layers[valid_layers[0]].append((l, r))
        else:
            layers.append([(l, r)])

    return len(layers)

