def find_min_layers(N):
    # We can solve this more efficiently
    # The minimal number of layers needed is equal to the maximum number
    # of overlapping intervals at any point

    # Count how many intervals contain each point
    point_coverage = {}
    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            # The point i is contained in the interval [i, j]
            point_coverage[i] = point_coverage.get(i, 0) + 1

    return max(point_coverage.values()) if point_coverage else 0

