def find_min_layers(N):
    # For each point, count how many intervals contain it
    # An interval [i, j] contains all points from i to j (inclusive)
    point_coverage = {}

    for i in range(N + 1):
        for j in range(i + 1, N + 1):
            for p in range(i, j + 1):
                point_coverage[p] = point_coverage.get(p, 0) + 1

    return max(point_coverage.values()) if point_coverage else 0

