        if 'A' in s_i:
            cost_A = min(cost_A, c_i)
        if 'B' in s_i:
            cost_B = min(cost_B, c_i)
        if 'C' in s_i:
            cost_C = min(cost_C, c_i)

        if 'AB' in s_i or ('A' in s_i and 'B' in s_i):
            cost_AB = min(cost_AB, c_i)
        if 'AC' in s_i or ('A' in s_i and 'C' in s_i):
            cost_AC = min(cost_AC, c_i)
        if 'BC' in s_i or ('B' in s_i and 'C' in s_i):
            cost_BC = min(cost_BC, c_i)

        if 'ABC' in s_i or ('A' in s_i and 'B' in s_i and 'C' in s_i):
            cost_ABC = min(cost_ABC, c_i)

    # Try all possible combinations to get all three vitamins
    min_cost = float('inf')

    # 1 juice
    if cost_ABC < min_cost:
        min_cost = cost_ABC

    # 2 juices
    if cost_AB + cost_C < min_cost:
        min_cost = cost_AB + cost_C
    if cost_AC + cost_B < min_cost:
        min_cost = cost_AC + cost_B
    if cost_BC + cost_A < min_cost:
        min_cost = cost_BC + cost_A

    # 3 juices
    if cost_A + cost_B + cost_C < min_cost:
        min_cost = cost_A + cost_B + cost_C

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

