a = list(map(int, input().split()))

if n < 3:
    print(0)
else:
    total = sum(a)

    # If total is not divisible by 3, answer is 0
    if total % 3 != 0:
        print(0)
    else:
        target = total // 3

        prefix = [0] * (n + 1)  # prefix[0] = 0, prefix[i] = sum of first i elements
        for i in range(n):
            prefix[i+1] = prefix[i] + a[i]

        count = 0

        # Find all positions i where sum of first i elements == target
        for i in range(1, n):
            if prefix[i] == target:
                # Now find how many ways to split the remaining part into two equal sums
                # Remaining array starts at index i+1, length = n-i
                # We need sum from i+1 to j = target
                j = i
                current_sum = 0
                for k in range(i+1, n+1):
                    current_sum += a[k-1]  # a[k-1] is the element at position k
                    if current_sum == target:
                        count += 1
                        current_sum = 0  # Reset for next cut position

        print(count)
