import sys

def derangements(n, values):
    """Count the number of derangements of a multiset of values for positions 1..n.
    values: list of values to be placed at positions 1..n (size n)
    Returns number of ways to assign values to positions without fixed points.
    """

    # Count occurrences of each value
    freq = {}
    for v in values:
        if v in freq:
            freq[v] += 1
        else:
            freq[v] = 1

    # Count number of each value type: value k appears in position k
    type1 = 0  # value k appears in position k
    type2 = 0  # value k appears in position not k

    for v in values:
        if v == 1:
            type1 += 1
        elif v == 2:
            type1 += 1
        elif v == 3:
            type1 += 1
        elif v == 4:
            type1 += 1
        elif v == 5:
            type1 += 1

    for v in range(1, n+1):
        if v not in freq:
            type2 += 1

    # DP: dp[i][j] = number of ways to assign first i values, j of which go to their correct positions
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(n - i + 1):
            if dp[i][j] == 0:
                continue

            # Try to place value at position i+1
            for v in freq:
                if freq[v] == 0:
                    continue

                # Place value v at position i+1
                if v == i + 1:
                    # This is a fixed point, can't do it
                    if j + 1 <= n:
                        dp[i + 1][j + 1] += dp[i][j]
                else:
                    # Not a fixed point, can do it
                    if j <= n:
                        dp[i + 1][j] += dp[i][j]

            freq[v] -= 1

    return dp[n][0]

