import sys

def count_derangements(m, values, positions):
    """Count derangements of m items where we have specific values and positions."""

    # values: list of values to be placed (size m)
    # positions: list of positions (1-indexed) (size m)
    # Count ways to assign values to positions with no fixed points

    # We need to count permutations of values to positions where value i ≠ position i
    # This is a derangement of a multiset

    # Inclusion-exclusion: D = sum_{k=0}^{m} (-1)^k * C(m, k) * (m-k)! 
    dp = [[0] * (m + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(i + 1):
            if dp[i][j] == 0:
                continue

            # Try to place the i-th element
            for k in range(1, m + 1):
                v = values[k - 1]
                p = positions[k - 1]
                if v == p:
                    # This creates a fixed point, can't do it
                    dp[i + 1][j] += dp[i][j]
