import sys

def count_derangements(m, bad):  # m = number of values to assign, bad = set of values that are bad (equal their position)
    """Count derangements of a set of size m with certain elements forbidden from being in their 'natural' position."""

    # We need to count permutations of {1..m} that avoid mapping bad[i] to position i
    # This is a standard derangement problem

    # Inclusion-exclusion: D = sum_{k=0}^{m} (-1)^k * C(m, k) * (m-k)! 
    dp = [[0] * (m + 1) for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(i + 1):
            if dp[i][j] == 0:
                continue

            # Try to place the i-th element
            for k in range(1, m + 1):
                if bad[k - 1] == k:
                    # This element is bad at its natural position
                    dp[i + 1][j] += dp[i][j]
                    dp[i + 1][j] %= 1000000007
                else:
                    # Not a fixed point
                    dp[i + 1][j + 1] += dp[i][j]
                    dp[i + 1][j + 1] %= 1000000007

    return dp[m][0]

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    filled_values = {}  # value -> position it occupies
    for i in range(n):
        if a[i] != -1:
            filled_values[a[i]] = i + 1

    # Find which values are missing
    missing = []
    for v in range(1, n + 1):
        if v not in filled_values:
            missing.append(v)

    # Find which positions have -1 (these are the positions we need to fill)
    filled_positions = []
    for i in range(n):
        if a[i] == -1:
            filled_positions.append(i + 1)

    # Count how many values are bad (value k appears in position k)
    bad = []
    for v in missing:
        pos = filled_positions[v - 1]  # v is the value, we need to check if it goes to position v
        if pos == v:
            bad.append(True)
        else:
            bad.append(False)

    m = len(missing)
    print(count_derangements(m, bad))

