import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    data = data[1:]

    upper = []
    lower = []
    odd_count = 0

    for i in range(n):
        x = int(data[2*i])
        y = int(data[2*i + 1])

        upper.append(x)
        lower.append(y)

        # Check if rotating this domino changes parity
        if (y - x) % 2 == 1:
            odd_count += 1

    # Calculate sum parities
    s_upper = sum(upper) % 2
    s_lower = sum(lower) % 2

    # If both parities are already even
    if s_upper == 0 and s_lower == 0:
        print(0)
        return

    # If both parities are the same (odd)
    if s_upper == s_lower:
        if odd_count >= 1:
            print(1)
        else:
            print(-1)
    else:
        if odd_count >= 2:
            print(2)
        else:
            print(-1)

if __name__ == "__main__":
    solve()
