def solve():
    s, k = input().split()
    k = int(k)

    n = int(input())
    bonus = {}
    for _ in range(n):
        x, y, c = input().split()
        bonus[(x, y)] = int(c)

    # dp[i][j][c] = max euphony at position i with j changes and last character c
    # c: 0-25 for 'a'-'z'
    dp = [[[-1 for _ in range(26)] for _ in range(k+1)] for _ in range(len(s))]

    # Base case: position 0
    for j in range(k+1):
        if j == 0:
            # No change at position 0
            last_char = ord(s[0]) - ord('a')
            dp[0][j][last_char] = 0
        else:
            # Change position 0
            for c in range(26):
                dp[0][j][c] = 0

    # Fill DP table
    for i in range(1, len(s)):
        for j in range(k+1):
            for last_c in range(26):
                if dp[i-1][j][last_c] == -1:
                    continue

                # Case 1: don't change current character
                curr_char = ord(s[i]) - ord('a')
                new_euphony = dp[i-1][j][last_c]
                if curr_char != last_c:
                    # Add bonus for transition from last_char to curr_char
                    if (chr(last_c + ord('a')), chr(curr_char + ord('a'))) in bonus:
                        new_euphony += bonus[(chr(last_c + ord('a')), chr(curr_char + ord('a')))]
                if dp[i][j][curr_char] < new_euphony:
                    dp[i][j][curr_char] = new_euphony

                # Case 2: change current character
                if j > 0:
                    for curr_c in range(26):
                        new_euphony = dp[i-1][j][last_c]
                        if curr_c != last_c:
                            if (chr(last_c + ord('a')), chr(curr_c + ord('a'))) in bonus:
                                new_euphony += bonus[(chr(last_c + ord('a')), chr(curr_c + ord('a')))]
                        if dp[i][j-1][curr_c] < new_euphony:
                            dp[i][j-1][curr_c] = new_euphony

    # Get the maximum value
    max_euphony = 0
    for j in range(k+1):
        for last_c in range(26):
            if dp[len(s)-1][j][last_c] > max_euphony:
                max_euphony = dp[len(s)-1][j][last_c]

    print(max_euphony)

solve()
