def max_gain(n, m, grid):
    # dp1[i][j]: max sum from (1,1) to (i,j) moving only right/down
    dp1 = [[0] * m for _ in range(n)]
    dp1[0][0] = grid[0][0]

    # dp2[i][j]: max sum from (n,1) to (i,j) moving only right/up
    dp2 = [[0] * m for _ in range(n)]
    dp2[n-1][0] = grid[n-1][0]

    # Fill dp1
    for i in range(n):
        for j in range(m):
            if i == 0 and j == 0:
                continue
            if i > 0:
                dp1[i][j] = dp1[i-1][j] + grid[i][j]
            if j > 0:
                dp1[i][j] = max(dp1[i][j], dp1[i][j-1] + grid[i][j])

    # Fill dp2
    for i in range(n-1, -1, -1):
        for j in range(m):
            if i == n-1 and j == 0:
                continue
            if i < n-1:
                dp2[i][j] = dp2[i+1][j] + grid[i][j]
            if j > 0:
