            # Iahub's path from (0,0) to (i,j)
            # Iahubina's path from (n-1, 0) to (i,j)
            iahub_sum = dp1[i][j]
            iahubina_sum = dp2[i][j]

            # Total gain when meeting at (i,j)
            total = iahub_sum + iahubina_sum

