def can_be_printed(s, t):
    i = 0  # pointer for s
    j = 0  # pointer for t

    while i < len(s):
        # Find the block of same characters in t starting at j
        if j >= len(t):
            return False

        char = t[j]
        end = j
        while end < len(t) and t[end] == char:
            end += 1

        # This block of characters in t corresponds to character s[i]
        if s[i] == char:
            i += 1
            j = end
        else:
            return False

    return j == len(t)

