import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []
    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        s = next(it)
        v = [None] * k
        ok = True
        for i in range(n):
            ch = s[i]
            r = i % k
            if ch == '0':
                if v[r] is not None:
                    if v[r] != 0:
                        ok = False
                else:
                    v[r] = 0
            elif ch == '1':
                if v[r] is not None:
                    if v[r] != 1:
                        ok = False
                else:
                    v[r] = 1
            else:  # '?', no action, v[r] remains None
                pass
        if not ok:
            out_lines.append("NO")
            continue
        known_sum = sum(1 for i in range(k) if v[i] == 1)
        free_count = 0
        for i in range(k):
            if v[i] is None:
                free_count += 1
        target = k // 2 - known_sum
        if 0 <= target <= free_count:
            out_lines.append("YES")
        else:
            out_lines.append("NO")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
"}

