def solve(s):
    n = len(s)
    count_0 = s.count('0')
    count_1 = n - count_0

    if count_1 > count_0:
        # More 1s than 0s
        # For each position, if suffix has more 1s than 0s, set to 1; else 0
        result = []
        for i in range(n):
            suffix_count_0 = s[i:].count('0')
            suffix_count_1 = n - i - suffix_count_0
            if suffix_count_1 > suffix_count_0:
                result.append('1')
            else:
                result.append('0')
