        n = int(next(it))
        seq = [int(next(it)) for _ in range(n)]
        total_sums.append(sum(seq))
        sequences.append(seq)

    # Dictionary: sum -> list of (sequence_index, element_index)
    sum_map = {}

    for seq_idx, seq in enumerate(sequences):
        total = total_sums[seq_idx]

        # Try removing each element
        for elem_idx in range(len(seq)):
            elem = seq[elem_idx]
            result_sum = total - elem

            # Store (sequence index, element index) (1-indexed)
            entry = (seq_idx + 1, elem_idx + 1)

            if result_sum not in sum_map:
                sum_map[result_sum] = []
            sum_map[result_sum].append(entry)

    # Check if any sum appears in at least two different sequences
    for key in sum_map:
        entries = sum_map[key]
        if len(entries) >= 2:
            # We need entries from different sequences
            seq_indices = set(e[0] for e in entries)
            if len(seq_indices) >= 2:
                # Find two entries from different sequences
