grid = []
for _ in range(n):
    grid.append(list(map(int, input().split())))

# dp_ih[i][j] = max calories from (1,1) to (i,j)
dp_ih = [[0] * m for _ in range(n)]
dp_ih[0][0] = grid[0][0]

# Fill dp_ih (only right and down moves)
for i in range(n):
    for j in range(m):
        if i > 0:
            dp_ih[i][j] = max(dp_ih[i][j], dp_ih[i-1][j] + grid[i][j])
        if j > 0:
            dp_ih[i][j] = max(dp_ih[i][j], dp_ih[i][j-1] + grid[i][j])

# dp_ihb[i][j] = max calories from (i,j) to (1,m)
dp_ihb = [[0] * m for _ in range(n)]
dp_ihb[n-1][0] = grid[n-1][0]

# Fill dp_ihb (only up and right moves)
for i in range(n-1, -1, -1):
    for j in range(m):
        if i < n-1:
            dp_ihb[i][j] = max(dp_ihb[i][j], dp_ihb[i+1][j] + grid[i][j])
        if j < m-1:
            dp_ihb[i][j] = max(dp_ihb[i][j], dp_ihb[i][j+1] + grid[i][j])

max_calories = 0
for i in range(n):
    for j in range(m):
        # Iahub goes from (1,1) to (i,j)
        # Iahubina goes from (n,1) to (i,j)
        # Then they continue
        total = dp_ih[i][j] + dp_ihb[i][j] - grid[i][j]
        max_calories = max(max_calories, total)

print(max_calories)
