# For i=1, we have the first character:
# We can choose to use that character or change it to any other character
for changes in range(k+1):
    for char in 'abcdefghijklmnopqrstuvwxyz':
        # If we keep the original character
        if changes <= k:
            dp[1][changes][char] = 0  # No bonus for a single character

        # If we change to this character (might be the original)
        if changes < k:
            # Cost to change is 1 if char != s[0]
            if char == s[0]:
                cost = 0
            else:
                cost = 1
            if dp[1][changes+1][char] < cost:
                dp[1][changes+1][char] = cost

