    for changes in range(k+1):
        for prev_char in 'abcdefghijklmnopqrstuvwxyz':
            # If dp[i-1][changes][prev_char] is not reachable, skip
            if dp[i-1][changes][prev_char] == -float('inf'):
                continue

            # Current character at position i-1
            curr_char = s[i-1]

            # Option 1: Keep the current character
            if changes <= k:
                curr_bonus = bonuses.get((prev_char, curr_char), 0)
                if dp[i][changes][curr_char] < dp[i-1][changes][prev_char] + curr_bonus:
                    dp[i][changes][curr_char] = dp[i-1][changes][prev_char] + curr_bonus

            # Option 2: Change the current character
            for new_curr_char in 'abcdefghijklmnopqrstuvwxyz':
                if changes < k:
                    new_bonus = bonuses.get((prev_char, new_curr_char), 0)
                    cost = 1 if new_curr_char != curr_char else 0
                    if dp[i][changes+1][new_curr_char] < dp[i-1][changes][prev_char] + new_bonus + cost:
