    x, y, c = input().split()
    bonus[(x, y)] = int(c)

# Initialize DP
# dp[i][j][c]: maximum bonus for first i characters (1-indexed), with j changes used, ending with character c
# dp is a list of dictionaries: dp[i][j][c] = value
# Initialize all values to -infinity
# We also need a special case for i=0 (0 characters)
INF = -float('inf')

# dp[i][j] = dictionary of {character: max bonus}
# dp[i][j] for i=0 means 0 characters
# dp[0][0] = { -1: 0 } (special case for 0 characters, -1 is a placeholder)
# For i > 0, we need a placeholder for the state before any characters
# We can use a special character like '*' to represent no previous character
# Or we can use a dictionary where we just don't have entries for those states
# For simplicity, let's use -1 as a special placeholder for 0 characters

# Initialize dp
len_s = len(s)
dp = [ [ { -1: 0 } for _ in range(k+1) ] for _ in range(len_s + 1) ]

# Fill DP
for i in range(1, len_s + 1):
    for j in range(k+1):
        for last_char, val in dp[i-1][j].items():
            # Option 1: Don't change current character (i-th position is s[i-1])
            current_char = s[i-1]
            if (last_char, current_char) in bonus:
                bonus_val = bonus[(last_char, current_char)]
            else:
                bonus_val = 0

            if dp[i][j].get(current_char, INF) < val + bonus_val:
                dp[i][j][current_char] = val + bonus_val

            # Option 2: Change current character to some other character (curr_char)
            if j < k:
                for curr_char in 'abcdefghijklmnopqrstuvwxyz':
                    if curr_char == current_char:
                        continue
                    if (last_char, curr_char) in bonus:
                        bonus_val = bonus[(last_char, curr_char)]
                    else:
                        bonus_val = 0

                    if dp[i][j+1].get(curr_char, INF) < val + bonus_val:
                        dp[i][j+1][curr_char] = val + bonus_val

# Find maximum possible bonus
max_bonus = INF
for j in range(k+1):
    for val in dp[len_s][j].values():
        if val > max_bonus:
            max_bonus = val

print(max_bonus)
