k = int(k)
n = int(input())
bonus = {}
for _ in range(n):
    x, y, c = input().split()
    bonus[(x, y)] = int(c)

# State: dp[i][j][c] = max bonus for first i characters, j changes used, ending with character c
# dp[i][j] is a dictionary mapping character to max value
# dp[i][j] for i=0 means 0 characters

# Initialize with a very large negative number for all states except dp[0][0][-1] = 0
INF = -float('inf')
len_s = len(s)

dp = [ [ { chr(c): INF for c in range(97, 123) } for _ in range(k+1) ] for _ in range(len_s + 1) ]

# Base case: 0 characters, 0 changes, ending with no character
dp[0][0][-1] = 0

# Fill DP
for i in range(1, len_s + 1):
    for j in range(k+1):
        for last_char, val in dp[i-1][j].items():
            current_char = s[i-1]

            # Option 1: Don't change current character
            if (last_char, current_char) in bonus:
                bonus_val = bonus[(last_char, current_char)]
            else:
                bonus_val = 0

            # Update dp[i][j]
            if val + bonus_val > dp[i][j].get(current_char, INF):
                dp[i][j][current_char] = val + bonus_val

            # Option 2: Change current character to some other character (curr_char)
            if j < k:
                for curr_char in 'abcdefghijklmnopqrstuvwxyz':
                    if curr_char == current_char:
                        continue

                    if (last_char, curr_char) in bonus:
                        bonus_val = bonus[(last_char, curr_char)]
                    else:
                        bonus_val = 0

                    if val + bonus_val > dp[i][j+1].get(curr_char, INF):
                        dp[i][j+1][curr_char] = val + bonus_val

# Find maximum
max_bonus = INF
for j in range(k+1):
