def combination(n, k):
    """Calculate n choose k"""
    if k > n or k < 0:
        return 0
    # n choose 2 = n*(n-1)//2
    if k == 2:
        return n * (n - 1) // 2
    # n choose 1 = n
    if k == 1:
        return n
    # n choose 3 = n*(n-1)*(n-2)//6
    if k == 3:
        return n * (n - 1) * (n - 2) // 6
    # Default (shouldn't happen)
    return n * (n - 1) // 2

# Read input
