# Sort the array
a.sort()

# Count frequencies
freq = {}
for num in a:
    freq[num] = freq.get(num, 0) + 1

# Find the smallest value and its count
smallest = a[0]
count_smallest = freq[smallest]

# If we have at least 3 of the smallest, we just need to choose 3
if count_smallest >= 3:
    print(combination(count_smallest, 3))
else:
    # We need at least 1 from the next smallest value
    # Find the next smallest value that has at least 1 element
    next_values = []
    for key in freq:
