def is_lonely(n):
    # A number x is lonely if for all y != x, x and y are not friends
    # Check if there exists any number y that is a friend of x
    for y in range(1, n + 1):
        if x == y:
            continue

        d = math.gcd(x, y)
        a = x // d
        b = y // d

        # Check triangle conditions
        cond1 = (d + a) > b
        cond2 = (d + b) > a
        cond3 = (a + b) > d

        if cond1 and cond2 and cond3:
            return False
    return True

