from itertools import combinations
import sys

def union_ranges(ranges):
    if not ranges:
        return 0

    # Sort ranges by left endpoint
    ranges.sort()

    # Merge overlapping ranges
    merged = [ranges[0]]
    for l, r in ranges[1:]:
        last_l, last_r = merged[-1]
        if l <= last_r + 1:
            # Overlapping or adjacent, merge
            merged[-1] = (last_l, max(last_r, r))
        else:
            merged.append((l, r))

    # Count sections covered
    return sum(r - l + 1 for l, r in merged)

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])
    ranges = []

    idx = 2
    for i in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        ranges.append((l, r))
        idx += 2

    max_covered = 0

    # Try all combinations of q-2 painters
    for chosen in combinations(ranges, q - 2):
        max_covered = max(max_covered, union_ranges(chosen))

    print(max_covered)

if __name__ == "__main__":
    main()
"}

