import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    times = list(map(int, data[1:n+1]))

    # Sort times in ascending order
    times.sort()

    count = 0
    cumulative_time = 0

    for time in times:
        if cumulative_time <= time:
            count += 1
            cumulative_time += time

    print(count)

if __name__ == "__main__":
    solve()
"}

